import { z } from "zod";

const {schemaName} = z.object({
  {fieldName}: z.string().min({minimumLength}),
});

type {typeName} = z.infer<typeof {schemaName}>;

const result = {schemaName}.safeParse({input});
if (!result.success) {
  console.error(result.error.flatten());
} else {
  const value = result.data;
}
